"""Authored backlog entries of wave 3: entries authored by merge pass 4 of 2026-11-16 (main-site workstream, plan round 1 of the closure workflow).

Why this wave exists: the batch handed to the engineers is the first 30 entries in order that have an authored acceptance (row C11), and since row C18 the order of the
authored entries is the roadmap path they serve first (survival, legacy A-line, grade A, full A+, optional) and the wave second. Waves 1 and 2 held only 30 ready
entries, 7 of them survival, while 18 survival entries and many legacy A-line entries had only a derived acceptance; this wave authors the most valuable of those
against the repository so that the batch is ordered by value and the next rounds do not start with an empty authored pool.

An entry here has the same fields as an entry of authored_wave1a.py (route, size, area, value, files, touches, reads, depends_on, acceptance, short, owed);
`short` is the sentence handed to an engineer in the dispatch list (at most 290 characters). Every premise in an acceptance was measured on release/R1g/dist (or
named tree) on the date in `basis`; a premise that a later pass finds inexact is corrected here and the correction is named in MERGE_NOTES of merge_status.py.
"""

WAVE3 = {}
WAVE3_ORDER = []


def A(i, **kw):
    kw.setdefault('wave', 3)
    kw.setdefault('basis', 'authored against the repository on 2026-11-16')
    WAVE3[i] = kw
    WAVE3_ORDER.append(i)


CAND = 'candidates/r1h/%s/'


def cand_files(i, extra=()):
    return [CAND % i + 'group.json', CAND % i + 'overlay/', CAND % i + 'test.mjs', CAND % i + 'STATUS.json', CAND % i + 'HANDOFF.md'] + list(extra)


def req_files(i):
    return ['docs/battle-theatre/GOVERNANCE/horde/requests/main-site-%s.md' % i, CAND % i + 'STATUS.json', CAND % i + 'HANDOFF.md']


